// ── WF8: Generar Reporte HTML desde la web ────────────────────────────────
const allItems = $input.all();
const attRows = allItems.filter(i => i.json.data_type === 'attendance').map(i => i.json);
const subRows  = allItems.filter(i => i.json.data_type === 'submission').map(i => i.json);
const now = new Date().toLocaleString('es-GT', { timeZone: 'America/Guatemala' });
const dateStr = new Date().toISOString().split('T')[0];
const reportName = 'web_report_' + dateStr + '_' + Date.now() + '.html';
const reportPath = '/data/shared/output/' + reportName;

const attTable = attRows.length === 0
  ? '<tr><td colspan="6" style="text-align:center;color:#94a3b8;padding:20px">Sin datos de asistencia aún</td></tr>'
  : attRows.map(r => {
    const rate = Number(r.rate||0);
    const rc = rate >= 80 ? '#16a34a' : rate >= 60 ? '#d97706' : '#dc2626';
    return '<tr><td><strong>' + r.course_id + '</strong></td><td>' + r.total + '</td>' +
      '<td style="color:#16a34a">' + r.present_count + '</td>' +
      '<td style="color:#dc2626">' + r.absent_count + '</td>' +
      '<td style="color:#d97706">' + r.late_count + '</td>' +
      '<td><span style="background:' + rc + ';color:#fff;padding:2px 8px;border-radius:10px;font-size:12px">' + rate + '%</span></td></tr>';
  }).join('');

const subTable = subRows.length === 0
  ? '<tr><td colspan="5" style="text-align:center;color:#94a3b8;padding:20px">Sin datos de entregas aún</td></tr>'
  : subRows.map(r => {
    const lr = r.total_submissions > 0 ? Math.round((r.late_count/r.total_submissions)*100) : 0;
    const lc = lr <= 10 ? '#16a34a' : lr <= 30 ? '#d97706' : '#dc2626';
    return '<tr><td><strong>' + r.task_id + '</strong></td><td>' + (r.task_name||'—') + '</td>' +
      '<td>' + r.total_submissions + '</td><td style="color:#dc2626">' + r.late_count + '</td>' +
      '<td><span style="background:' + lc + ';color:#fff;padding:2px 8px;border-radius:10px;font-size:12px">' + lr + '%</span></td></tr>';
  }).join('');

const html = `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8">
<link href="https://fonts.googleapis.com/css2?family=Figtree:wght@400;500;600;700&display=swap" rel="stylesheet">
<title>Reporte Académico — ${dateStr}</title>
<style>
*{box-sizing:border-box;margin:0;padding:0}body{font-family:'Figtree',sans-serif;background:#f0f4ff;color:#1e293b;padding:28px}
.hdr{background:linear-gradient(135deg,#1e40af 0%,#7c3aed 100%);color:#fff;padding:28px 32px;border-radius:14px;margin-bottom:24px}
.hdr h1{font-size:22px;font-weight:700;margin-bottom:6px}.hdr p{opacity:.85;font-size:13px}
.section{background:#fff;border-radius:12px;overflow:hidden;box-shadow:0 1px 6px rgba(0,0,0,.07);margin-bottom:20px}
.sec-hdr{padding:14px 20px;background:#f8fafc;border-bottom:1px solid #e2e8f0;font-weight:600;color:#374151;font-size:14px}
table{width:100%;border-collapse:collapse}
th{background:#1e40af;color:#fff;padding:11px 12px;text-align:left;font-size:13px;font-weight:600}
td{padding:10px 12px;border-bottom:1px solid #f1f5f9;font-size:13px}tr:last-child td{border:none}
tr:hover td{background:#f8fafc}.footer{text-align:center;color:#94a3b8;font-size:12px;margin-top:16px}</style></head>
<body>
<div class="hdr"><h1>📊 Reporte Académico</h1><p>Generado: ${now} &nbsp;|&nbsp; Archivo: ${reportName}</p></div>
<div class="section">
  <div class="sec-hdr">📋 Asistencia por Curso</div>
  <table><thead><tr><th>Curso</th><th>Total</th><th>Presentes</th><th>Ausentes</th><th>Tardanzas</th><th>Tasa</th></tr></thead>
  <tbody>${attTable}</tbody></table>
</div>
<div class="section">
  <div class="sec-hdr">📁 Entregas por Tarea</div>
  <table><thead><tr><th>ID Tarea</th><th>Nombre</th><th>Entregas</th><th>Tardías</th><th>% Tardías</th></tr></thead>
  <tbody>${subTable}</tbody></table>
</div>
<div class="footer">AcademicFlow — n8n ${dateStr}</div>
</body></html>`;

const safe = s => String(s||'').replace(/'/g,"''");
const rpt_sql = "INSERT INTO reports (report_type, file_path, status, records_count) VALUES ('web_full', '" +
  safe(reportPath) + "', 'generated', " + (attRows.length+subRows.length) + ")";

return [{
  json: { ok: true, reportName, reportPath, rpt_sql, attCount: attRows.length, subCount: subRows.length, generatedAt: now },
  binary: { report: { data: Buffer.from(html).toString('base64'), mimeType:'text/html', fileName:reportName, fileExtension:'html' } }
}];
